Patch the random function using `unittest.mock`:
import unittest
from unittest.mock import patch

def foo():
    return random.randint(1, 10)

class TestFoo(unittest.TestCase):
    @patch('module_under_test.random.randint', return_value=5)
    def test_foo(self, mock_randint):
        self.assertEqual(foo(), 5)

if __name__ == '__main__':
    unittest.main()
